CREATE TABLE "tenant_closure" (
	"ancestor_id" uuid NOT NULL,
	"descendant_id" uuid NOT NULL,
	"depth" integer NOT NULL,
	CONSTRAINT "tenant_closure_ancestor_id_descendant_id_pk" PRIMARY KEY("ancestor_id","descendant_id"),
	CONSTRAINT "tenant_closure_depth" CHECK ("tenant_closure"."depth" >= 1),
	CONSTRAINT "tenant_closure_not_self" CHECK ("tenant_closure"."ancestor_id" <> "tenant_closure"."descendant_id")
);
